import requests
from urllib.parse import quote
terms=['"A qualitative study" female burn injuries India medicolegal','female burn injuries India in-hospital medicolegal response','burn injuries women India qualitative medicolegal']
for q in terms:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&retmode=json&retmax=10&term='+quote(q)
 r=requests.get(u,timeout=20); print('\nQUERY',q,'STATUS',r.status_code); ids=r.json().get('esearchresult',{}).get('idlist',[]); print('IDS',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'),x[i].get('fulljournalname'))

import requests, xml.etree.ElementTree as ET
pmid='25433681'
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':pmid,'rettype':'abstract','retmode':'xml'},timeout=20); print('PUBMED_STATUS',r.status_code); root=ET.fromstring(r.text)
for a in root.findall('.//ArticleTitle'): print('TITLE',''.join(a.itertext()))
for a in root.findall('.//Abstract/AbstractText'): print('ABSTRACT',a.get('Label',''),''.join(a.itertext()))
for a in root.findall('.//ELocationID'): print('ELocation',a.get('EIdType'),''.join(a.itertext()))
for a in root.findall('.//ArticleId'): print('ID',a.get('IdType'),a.text)
